#include "scheduler.h"

#include <assert.h>
#include <stdio.h>

static void test_bulk_complete_applies_all_when_every_id_is_running(void) {
    Scheduler s;
    scheduler_init(&s);
    int id1 = scheduler_submit(&s, 1, "a");
    int id2 = scheduler_submit(&s, 1, "b");
    int r;
    scheduler_run_next(&s, &r);
    scheduler_run_next(&s, &r);

    int ids[2] = { id1, id2 };
    assert(scheduler_complete_bulk(&s, ids, 2) == 1);

    JobState st;
    scheduler_find_state(&s, id1, &st);
    assert(st == JOB_DONE);
    scheduler_find_state(&s, id2, &st);
    assert(st == JOB_DONE);
}

static void test_bulk_complete_rejects_whole_batch_on_one_bad_id(void) {
    Scheduler s;
    scheduler_init(&s);
    int id1 = scheduler_submit(&s, 1, "a");
    int r;
    scheduler_run_next(&s, &r);

    int ids[2] = { id1, 999999 };
    assert(scheduler_complete_bulk(&s, ids, 2) == 0);

    JobState st;
    scheduler_find_state(&s, id1, &st);
    assert(st == JOB_RUNNING);
}

int main(void) {
    test_bulk_complete_applies_all_when_every_id_is_running();
    test_bulk_complete_rejects_whole_batch_on_one_bad_id();
    printf("PASS\n");
    return 0;
}

