#pragma once

#include "job.h"
#include "queue.h"

#define SCHEDULER_MAX_RUNNING 256
#define SCHEDULER_MAX_HISTORY 256

typedef struct {
    JobQueue pending;
    Job running[SCHEDULER_MAX_RUNNING];
    int running_count;
    Job history[SCHEDULER_MAX_HISTORY];
    int history_count;
} Scheduler;

void scheduler_init(Scheduler *s);
int scheduler_submit(Scheduler *s, int priority, const char *payload);
int scheduler_run_next(Scheduler *s, int *out_id);
int scheduler_complete(Scheduler *s, int id);
int scheduler_fail(Scheduler *s, int id);
int scheduler_find_state(const Scheduler *s, int id, JobState *out_state);

/*
 * Completes a batch of running jobs atomically: every id in `ids`
 * (length `count`) must currently be RUNNING before ANY of them are
 * marked DONE - one bad id anywhere in the batch leaves every job's
 * state untouched. Returns 1 if the whole batch was completed, 0 if
 * it was rejected (and nothing changed).
 */
int scheduler_complete_bulk(Scheduler *s, const int *ids, int count);

